import{_ as e,o as n,c as i,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Video Space + Claude: kết quả nối vào BrandHub","description":"","frontmatter":{},"headers":[],"relativePath":"feature/video-space/RECONNECT_RESULT_2026-11-09.md","filePath":"feature/video-space/RECONNECT_RESULT_2026-11-09.md"}'),o={name:"feature/video-space/RECONNECT_RESULT_2026-11-09.md"};function c(d,t,r,h,l,s){return n(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="video-space-claude-ket-qua-noi-vao-brandhub" tabindex="-1">Video Space + Claude: kết quả nối vào BrandHub <a class="header-anchor" href="#video-space-claude-ket-qua-noi-vao-brandhub" aria-label="Permalink to &quot;Video Space + Claude: kết quả nối vào BrandHub&quot;">​</a></h1><p>Ngày kiểm tra: 09/11/2026. Thay đổi đang ở local, chưa commit/push.</p><h2 id="phan-đa-noi" tabindex="-1">Phần đã nối <a class="header-anchor" href="#phan-đa-noi" aria-label="Permalink to &quot;Phần đã nối&quot;">​</a></h2><ul><li>Business API lưu/mở dự án riêng theo user và workspace, revision/CAS, media upload-session/confirm/abort, khôi phục và tính quota; đọc video AI đã hoàn thành để mở trong editor.</li><li>Nút <strong>Trợ lý AI</strong> trong editor: nhập yêu cầu → lưu bản hiện tại → Claude lập kế hoạch → xem trước → áp dụng bằng command native; Undo một bước.</li><li>Claude dùng API/key/model cấu hình sẵn trong AI service. Hướng dẫn biên tập được đóng gói tại <code>brandhub-ai-service/app/resources/video-edit/editorial-guide.md</code>, có nguồn DemoVideo và giới hạn sử dụng rõ ràng. Không chạy shell/code do model sinh ra.</li><li>Tám thao tác: đổi tên, đổi tỷ lệ, thêm/sửa chữ, âm lượng, cắt clip, tốc độ và chuyển cảnh đã có trong engine. Thay đổi vẫn chỉnh thủ công và xuất bằng editor được.</li><li>Cầu nối iframe giữ token ở host; chỉ cho phép endpoint edit-plan của dự án đang mở, có idempotency và kiểm tra revision/nội dung hiện tại trước khi áp dụng.</li><li>Video AI có đường dẫn theo workspace và nút quay về giữ đúng workspace.</li></ul><p>Mở: <code>http://localhost:3000/workspaces/d3210000-0000-4000-8000-000000000003/video-space</code></p><p>Video AI: <code>http://localhost:3000/workspaces/d3210000-0000-4000-8000-000000000003/ai-studio/video</code></p><h2 id="bang-chung" tabindex="-1">Bằng chứng <a class="header-anchor" href="#bang-chung" aria-label="Permalink to &quot;Bằng chứng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kiểm tra</th><th>Kết quả</th></tr></thead><tbody><tr><td>Business kiểm thử feature</td><td>67 test qua</td></tr><tr><td>Business toàn bộ báo cáo Surefire trong worktree sạch</td><td>1741 test, 0 lỗi/0 thất bại, 91 bỏ qua</td></tr><tr><td>AI regression offline</td><td>120 test qua trước sửa parser native; bộ planner cuối 51 test qua</td></tr><tr><td>FFmpeg renderer thật với nguồn tổng hợp</td><td>7 test qua, có kiểm tra pixel/chữ/logo/âm thanh</td></tr><tr><td>Host bridge/credit unit</td><td>14 test qua</td></tr><tr><td>Native command/concurrency unit</td><td>14 test qua, gồm Undo/Redo và dữ liệu cũ</td></tr><tr><td>Web lint/type-check/build</td><td>Qua; còn cảnh báo lint/chunk có sẵn, không có lỗi chặn build</td></tr><tr><td>API thật qua Gateway</td><td>Login/list/save/read200; stale save409; khác workspace404; thiếu idempotency400</td></tr><tr><td>Claude API thật</td><td>200, khoảng2,7giây; đổi tên + thêm chữ; gửi lại cùng key trả đúng kết quả đã lưu</td></tr><tr><td>Browser riêng, fixture</td><td>Kế hoạch AI → áp dụng chữ/âm lượng → Undo qua; không gọi model/video trả phí trong browser test</td></tr><tr><td>Mở video AI, sửa, lưu, phiên mới, xuất MP4</td><td>Qua; MP4 giải mã640×360, pixel giữa[65,65,65], góc[0,0,0] đúng mask/filter</td></tr></tbody></table><p>Bằng chứng local: <code>.tmp/video-connect-20261109/</code> và <code>.tmp/video-space-e2e/</code> tại workspace gốc. Bài browser cũ hỏng do selector/menu cũ và mất workspace ở global route; đã sửa đường dẫn theo workspace, dùng selector href và chạy lại qua.</p><h2 id="database-va-du-lieu" tabindex="-1">Database và dữ liệu <a class="header-anchor" href="#database-va-du-lieu" aria-label="Permalink to &quot;Database và dữ liệu&quot;">​</a></h2><ul><li>Có backup PostgreSQL <code>postgres-before-connect.dump</code> trước thay đổi.</li><li>Đã thử migration trên bản sao <code>brandhub_video_connect_verify_20261109</code>, sau đó áp dụng schema quota/runtime, Product Video và manager-sharing cần cho code hiện tại vào local.</li><li>Checksum toàn bộ <code>billing_plan_versions</code> không thay đổi; không seed giá/credit, không xóa bảng legacy, không tắt trigger immutable.</li><li>Thêm đúng4index của3collection <code>video_projects</code>, <code>video_project_assets</code>, <code>video_project_upload_sessions</code>; không sửa document tasks/posts/mail cũ.</li></ul><h2 id="gioi-han-con-lai" tabindex="-1">Giới hạn còn lại <a class="header-anchor" href="#gioi-han-con-lai" aria-label="Permalink to &quot;Giới hạn còn lại&quot;">​</a></h2><p><strong>Đã xử lý lệch cấu hình AWS ngày09/11:</strong> Business dùng cặp key khác AI. Key AI xác thực STS và đọc đúng bucket/CORS thành công; key Business cũ trả <code>InvalidClientTokenId</code>/<code>InvalidAccessKeyId</code>. Đã sao lưu <code>.env</code> vào file bị Git bỏ qua, đồng bộ riêng <code>AWS_ACCESS_KEY_ID</code> và <code>AWS_SECRET_ACCESS_KEY</code> từ AI sang Business, giữ nguyên bucket/region và restart Business thành công. Kiểm tra lại cả hai cặp đều xác thực STS/head bucket/CORS thành công; không cần chuyển MinIO hay tạo key mới. Chưa chạy PUT media hoặc tạo video thật trong bước kiểm tra key này. Lưu snapshot và Claude text-plan đã chạy thật, media/end-to-end trong browser dùng fixture.</p><p>Claude hiện xử lý metadata, chữ, thời lượng và cấu trúc timeline. Chưa tự xem/nghe toàn bộ footage, tìm nhạc/SFX hay thực thi toàn bộ tác vụ DemoVideo tùy ý. Kế hoạch cần người dùng bấm Áp dụng. Không triển khai VM và không chạy lượt tạo video Veo trả phí trong lần nối này. Product Video renderer/coordinator đã khôi phục source, nhưng tạo cảnh thật vẫn cần provider/journal/cloud readiness riêng.</p><h2 id="quyet-đinh-trien-khai" tabindex="-1">Quyết định triển khai <a class="header-anchor" href="#quyet-đinh-trien-khai" aria-label="Permalink to &quot;Quyết định triển khai&quot;">​</a></h2><ul><li>Khôi phục source đã lưu trong stash, chỉ ghép các phần Video Space/Product Video vào code mới; giữ các thay đổi caption/trend/I2V khác. Sai khác nếu có sẽ cần sửa cục bộ, không bị mất baseline vì đã lưu patch/hash.</li><li>Tái dùng <code>CONTENT_GENERATE</code> và cơ chế credit/idempotency hiện có cho lập kế hoạch text; không thêm bảng giá hay đường bỏ qua thanh toán. Nếu muốn tính giá riêng sau này cần operation/pricing được duyệt riêng.</li><li>Chỉ dùng hướng dẫn biên tập có nguồn và action whitelist; không đưa recipe/code SeeCut-VN Noncommercial vào runtime thương mại.</li><li>Giữ worktree/manifest kiểm tra vì chưa commit; không xóa bản làm việc chưa được ghi vào Git.</li><li>Reviewer subagent cuối không chạy được do giới hạn tài khoản của công cụ; controller đã rà soát tích hợp, sửa parser native/empty caption/font/route và chạy các kiểm tra nêu trên. Chưa có chứng cứ review độc lập cuối cùng.</li></ul>',16)])])}const p=e(o,[["render",c]]);export{g as __pageData,p as default};
